 "content": "from collections import Counter


def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    if any(len(row) != len(grid[0]) for row in grid):
        raise ValueError("grid rows must have equal width")

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A complete horizontal bar of a color serves as the template for a
    # matching left-anchored partial bar: extend its blank suffix in color 1.
    full_colors = {
        row[0]
        for row in grid
        if row[0] != bg and all(cell == row[0] for cell in row)
    }
    candidates = []
    for r, row in enumerate(grid):
        if row[0] == bg:
            continue
        color = row[0]
        end = 0
        while end < w and row[end] == color:
            end += 1
        if 0 < end < w and all(cell == bg for cell in row[end:]) and color in full_colors:
            candidates.append((r, end))

    if len(candidates) == 1:
        r, end = candidates[0]
        out[r][end:] = [1] * (w - end)
    return out


